CREATE TABLE mistri.tenant_membership (
    id text NOT NULL COLLATE pg_catalog."C",
    tenant_id text NOT NULL COLLATE pg_catalog."C",
    account_id text NOT NULL COLLATE pg_catalog."C",
    status text NOT NULL COLLATE pg_catalog."C",
    version text NOT NULL COLLATE pg_catalog."C",
    roles_json text NOT NULL,
    valid_until bigint NOT NULL,
    kind text NOT NULL COLLATE pg_catalog."C",
    parent_id text COLLATE pg_catalog."C",
    parent_version text COLLATE pg_catalog."C",
    platform_version text COLLATE pg_catalog."C",
    CONSTRAINT tenant_membership_check CHECK (((kind = 'support'::text) = ((parent_id IS NOT NULL) AND (parent_version IS NOT NULL) AND (platform_version IS NOT NULL)))),
    CONSTRAINT tenant_membership_check1 CHECK (((kind = 'member'::text) OR (status = ANY (ARRAY['active'::text, 'revoked'::text])))),
    CONSTRAINT tenant_membership_kind_check CHECK ((kind = ANY (ARRAY['member'::text, 'support'::text]))),
    CONSTRAINT tenant_membership_roles_json_check CHECK (((octet_length(roles_json) <= 262144) AND (json_typeof((roles_json)::json) = 'array'::text))),
    CONSTRAINT tenant_membership_status_check CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text, 'invited'::text]))),
    CONSTRAINT tenant_membership_valid_until_check CHECK (((valid_until >= 0) AND (valid_until <= '9007199254740991'::bigint)))
);
CREATE TABLE mistri.tenant_meta (
    singleton integer NOT NULL,
    version integer NOT NULL,
    app_id text NOT NULL COLLATE pg_catalog."C",
    source_id text NOT NULL COLLATE pg_catalog."C",
    store_id text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT tenant_meta_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT tenant_meta_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.tenant_tenant (
    id text NOT NULL COLLATE pg_catalog."C",
    status text NOT NULL COLLATE pg_catalog."C",
    version text NOT NULL COLLATE pg_catalog."C",
    kind text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT tenant_tenant_check CHECK (((kind = 'platform'::text) = (id = '@platform'::text))),
    CONSTRAINT tenant_tenant_kind_check CHECK ((kind = ANY (ARRAY['tenant'::text, 'platform'::text]))),
    CONSTRAINT tenant_tenant_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'closed'::text])))
);
